def search(items, target, lo, hi):
    if lo > hi:
        return -1
    mid = (lo + hi) // 2
    print(f"  look at position {mid}: {items[mid]}")
    if items[mid] == target:
        return mid
    if items[mid] < target:
        return search(items, target, mid + 1, hi)
    return search(items, target, lo, mid - 1)

