memo = {}

def fib(n, depth=0):
    pad = "  " * depth
    if n in memo:
        print(pad + f"fib({n}) remembered")
        return memo[n]
    print(pad + f"fib({n})")
    if n < 2:
        result = n
    else:
        result = fib(n - 1, depth + 1) + fib(n - 2, depth + 1)
    memo[n] = result
    return result

