    def __init__(self, number):
        self.number = number

    def __eq__(self, other):
        Guest.comparisons += 1
        return self.number == other.number

    def __hash__(self):
        return hash(self.number)

def linear_steps(numbers, target):
    steps = 0
    for item in numbers:
        steps += 1
        if item == target:
            break
    return steps

def binary_steps(numbers, target):
    steps, lo, hi = 0, 0, len(numbers) - 1
    while lo <= hi:
        steps += 1
        mid = (lo + hi) // 2
        if numbers[mid] == target:
            break
        if numbers[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return steps

def set_steps(n, target):
    vip = {Guest(k) for k in range(n)}
    Guest.comparisons = 0
    Guest(target) in vip
    return Guest.comparisons

print("guests linear binary set")
for n in [1000, 2000, 4000, 8000]:
    numbers = list(range(n))
    last = n - 1
    print(n, linear_steps(numbers, last), binary_steps(numbers, last), set_steps(n, last))

