folders = {
    "home": {
        "photos": {"cat.jpg": 120, "dog.jpg": 90},
        "notes.txt": 4,
        "music": {"rock": {"song.mp3": 300}},
    }
}

def show(tree, depth=0):
    for name, value in tree.items():
        if isinstance(value, dict):
            print("  " * depth + name + "/")
            show(value, depth + 1)
        else:
            print("  " * depth + f"{name} ({value} KB)")

def size(tree):
    total = 0
    for value in tree.values():
        if isinstance(value, dict):
            total += size(value)
        else:
            total += value
    return total

show(folders)
print("total:", size(folders), "KB")
